  const createRelationship=()=>run(()=>{if(!supplier)throw new Error('supplier_required');apply(createSupplierRelationshipV2029(state,{supplier_id:supplier,legal_entity_id:factory.business_unit_id,supplier_code:code,payment_terms_days:30,credit_limit:'0',credit_currency:currency,default_currency:currency,effective_from:today()},actor))});
