  const credit=()=>run(()=>{if(!rel)throw new Error('customer_relationship_required');apply(createCustomerCreditProfileV2029(state,{relationship_id:rel.id,credit_limit:String(customer?.credit_limit_sar||100000),credit_currency:currency,credit_days:customer?.credit_days||30,grace_days:0,risk_category:'low',effective_from:today()},actor))});
  const order=()=>run(()=>{if(!customer||!rel)throw new Error('customer_relationship_required');if(!productId)throw new Error('finished_product_required');const p=mb.products.find((x:any)=>x.id===productId);apply(createSalesOrderControlV2029(state,{relationship_id:rel.id,customer_id:customer.id,legal_entity_id:factory.business_unit_id,factory_id:factory.id,order_date:today(),requested_delivery_date:today(),currency,exchange_rate_to_sar:fx,lines:[{product_id:productId,quantity_kg:qty,bag_weight_kg:p?.bag_weight_kg||50,unit_price:price}],credit_check_status:'pending'},actor))});
  const draft=ext.sales_orders.find((x:any)=>x.status==='draft');
  const confirm=()=>run(()=>{if(!draft)throw new Error('draft_sales_order_required');const snap=salesOrderCreditSnapshotV2029(state,mb,draft.id);if(!snap.approved)throw new Error(`credit_requires_approval: exposure=${snap.exposure_sar}, available=${snap.available_credit_sar}`);apply(confirmSalesOrderV2029(state,draft.id,snap,true,actor))});
