  const invoiceEligible=ext.sales_dispatches.find((x:any)=>['dispatched','delivered'].includes(x.status)&&!ext.sales_invoices.some((i:any)=>i.dispatch_reference_id===x.id&&i.status==='posted_to_ar'));
  const invoice=()=>run(()=>{if(!invoiceEligible)throw new Error('eligible_sales_dispatch_required');const r=postFactorySalesInvoiceToARV2029(state,mb,web,{sales_order_id:invoiceEligible.sales_order_id,dispatch_reference_id:invoiceEligible.id,invoice_date:today(),actor});apply(r.state);onBusinessChange(r.multiBusiness);onWebChange(r.web)});
  const postedInvoice=ext.sales_invoices.find((x:any)=>x.status==='posted_to_ar'),treasury=mb.treasury_accounts.find((x:any)=>x.business_unit_id===factory.business_unit_id&&x.active);
  const [receiptAmount,setReceiptAmount]=useState(''),[returnQty,setReturnQty]=useState('50'),[returnReason,setReturnReason]=useState('Customer return');
  const receipt=()=>run(()=>{if(!customer||!rel||!treasury)throw new Error('customer_relationship_and_treasury_required');const inv=postedInvoice;const amount=receiptAmount||inv?.total_amount||'0';const r=recordFactoryCustomerReceiptV2029(state,mb,web,{relationship_id:rel.id,customer_id:customer.id,invoice_id:inv?.id,treasury_account_id:treasury.id,receipt_date:today(),currency:inv?.currency||currency,original_amount:amount,exchange_rate_to_sar:inv?.exchange_rate_to_sar||fx,actor});apply(r.state);onBusinessChange(r.multiBusiness);onWebChange(r.web);setReceiptAmount('')});
