  const approveReturn=()=>run(()=>{const row=ext.sales_returns.find((x:any)=>x.status==='draft');if(!row)throw new Error('draft_sales_return_required');apply(approveFactorySalesReturnV2029(state,row.id,actor))});
  const receiveReturn=()=>run(()=>{const row=ext.sales_returns.find((x:any)=>x.status==='approved');if(!row)throw new Error('approved_sales_return_required');const r=receiveFactorySalesReturnV2029(state,mb,row.id,actor);apply(r.state);onBusinessChange(r.multiBusiness)});
