  const pending=web.expenses.find((x:any)=>x.status==='pending');const approveExpense=()=>run(()=>{if(!pending)throw new Error('pending_expense_required');onWebChange(decideExpenseV202(web,pending.id,true,actor,'FINANCE_OFFICER','factory_expense_approved'))});

  const openPeriod=()=>run(()=>{const month=today().slice(0,7);onWindowsChange(createAccountingPeriodV2027(windows,{code:periodCode,business_unit_id:factory.business_unit_id,date_from:`${month}-01`,date_to:today()},actor))});
  const closePeriod=()=>run(()=>{const row=windows.accounting_periods.find((x:any)=>x.business_unit_id===factory.business_unit_id&&['open','reopened'].includes(x.status));if(!row)throw new Error('open_accounting_period_required');onWindowsChange(closeAccountingPeriodV2027(windows,web,row.id,actor,'Factory period close'))});
