  const customerRows=mb.counterparty_ledger.filter((x:any)=>x.party_type==='customer'&&x.business_unit_id===factory.business_unit_id),supplierRows=mb.counterparty_ledger.filter((x:any)=>x.party_type==='supplier'&&x.business_unit_id===factory.business_unit_id);
  const ar=customerRows.reduce((sum:number,x:any)=>sum+x.debit_sar-x.credit_sar,0),ap=supplierRows.reduce((sum:number,x:any)=>sum+x.credit_sar-x.debit_sar,0);
