  <Panel title="Posted Journal History — immutable"><Table h={['Journal','Date','Description','Source','Debit','Credit','Status']} r={web.journal_entries.slice(0,100).map((x:any)=>[x.journal_number,x.journal_date,x.description,`${x.source_type}:${x.source_id}`,n(x.lines.reduce((a:number,l:any)=>a+l.debit_sar,0)),n(x.lines.reduce((a:number,l:any)=>a+l.credit_sar,0)),x.status])}/></Panel>
