const Title:React.FC<{n:string;ar:string;en:string}>=({n,ar,en})=><div className="mt-5 flex items-center gap-3"><div className="w-9 h-9 rounded-xl bg-cyan-500/15 border border-cyan-500/30 flex items-center justify-center text-cyan-300 font-black">{n}</div><div><div className="text-base font-black text-white">{ar}</div><div className="text-[10px] text-slate-500 font-bold">{en}</div></div></div>;
const Panel:React.FC<{title:string;children:React.ReactNode}>=({title,children})=><div className="mt-4 rounded-2xl border border-slate-800 bg-slate-950/50 p-3"><div className="text-xs font-black text-slate-200 mb-3">{title}</div>{children}</div>;
const Hint:React.FC<{children:React.ReactNode}>=({children})=><div className="mt-3 rounded-xl border border-amber-500/20 bg-amber-500/5 p-3 text-[11px] text-amber-200">{children}</div>;
const Badge:React.FC<{ok:boolean;text:string}>=({ok,text})=><div className={`rounded-xl border px-3 py-2 text-xs font-black ${ok?'border-emerald-500/30 bg-emerald-500/5 text-emerald-300':'border-amber-500/30 bg-amber-500/5 text-amber-300'}`}>{text}</div>;
const Rule:React.FC<{t:string;d:string}>=({t,d})=><div className="rounded-xl border border-slate-800 p-2 bg-slate-950/50"><div className="font-black text-cyan-300">{t}</div><div className="text-slate-400 mt-1">{d}</div></div>;
const Metrics:React.FC<{rows:Array<[string,React.ReactNode]>}>=({rows})=><div className="mt-4 grid grid-cols-2 md:grid-cols-4 xl:grid-cols-7 gap-2">{rows.map(([k,v])=><div key={k} className="rounded-xl border border-slate-800 bg-slate-950/50 p-2"><div className="text-[9px] text-slate-500 font-bold">{k}</div><div className="text-sm font-black text-white mt-1">{v}</div></div>)}</div>;
const Table:React.FC<{h:string[];r:Array<Array<React.ReactNode>>}>=({h,r})=><div className="overflow-x-auto"><table className="w-full text-[11px]"><thead><tr className="border-b border-slate-800">{h.map(x=><th key={x} className="text-right px-2 py-2 text-slate-500 whitespace-nowrap">{x}</th>)}</tr></thead><tbody>{r.length?r.map((row,i)=><tr key={i} className="border-b border-slate-900">{row.map((c,j)=><td key={j} className="px-2 py-2 text-slate-300 whitespace-nowrap">{c}</td>)}</tr>):<tr><td colSpan={h.length} className="p-5 text-center text-slate-600">لا توجد بيانات بعد.</td></tr>}</tbody></table></div>;
